<?php
namespace App\Filament\Widgets;
use Filament\Widgets\ChartWidget;
use Illuminate\Support\Facades\DB;
class SalesChartWidget extends ChartWidget { protected static ?string $heading = 'Продажи по дням'; protected int|string|array $columnSpan = 'full'; protected function getData(): array { $data = DB::table('payments')->select(DB::raw('DATE(paid_at) as date'),DB::raw('SUM(amount) as total'))->where('status','succeeded')->where('paid_at','>=',now()->subDays(14))->groupBy('date')->orderBy('date')->get()->keyBy('date'); $labels=[];$values=[];for($i=13;$i>=0;$i--){ $d=now()->subDays($i)->format('Y-m-d'); $labels[]=now()->subDays($i)->format('d.m'); $values[]=($data[$d]->total ?? 0)/100; } return ['datasets'=>[['label'=>'Выручка, ₽','data'=>$values,'borderColor'=>'#f59e0b','backgroundColor'=>'#fbbf24']],'labels'=>$labels]; } protected function getType(): string { return 'line'; } }